export type AbiLayout = typeof ABI_LAYOUT;
export type AbiStructureName = keyof AbiLayout["structures"];
export type AbiStructure = AbiLayout["structures"][AbiStructureName];
export type AbiField = AbiStructure["fields"][number];
export type AbiConstantName = keyof AbiLayout["constants"];
export type AbiCommandField = AbiLayout["commandRecord"]["fields"][number];
/** Where a typed SDK refusal was raised. Replaces the dead two-phase "compile". */
export type ErrorPhase = AbiLayout["errorPhases"][number];
export type ResultCodeName = AbiLayout["constants"]["resultCodes"][number]["name"];
/** Boot's return reads through this table; every other call reads the base names. */
export type BootResultAliasName =
  AbiLayout["constants"]["bootResultAliases"][number]["name"];
export type BufferKindName = AbiLayout["constants"]["bufferKinds"][number]["name"];
export type BootExportName = AbiLayout["stagingSequence"][number];
/** Every module export, so no SDK call site types a symbol name. */
export type ExportName = AbiLayout["exports"][number];
